    --sv-ava: 192px;              /* 大头像边长（电脑）：96 的整数倍最清楚 */
    --sv-ava-m: 96px;             /* 手机 */
    --sv-ava-render: pixelated;   /* 头像放大方式：pixelated = 像素颗粒；auto = 平滑 */
    --sv-gap: 18px;               /* 消息之间的距离 */
    --sv-card-px: 1.5px;            /* 人物卡（角色列表的头像框）的一格多大 */
    --sv-lpanel: 420px;           /* 左边面板（预设、AI 设置）至少多宽（电脑）：比聊天区两边的空白宽时，盖住聊天区一点，顶栏那一行让出来 */
    --sv-deco: 1;                 /* 装饰（叶子）：1 = 显示，0 = 不要 */

    /* 像素字：SV RoundPix / SV Fusion 是主题伴侣自带的那份，ZeoSeven 的是没装伴侣时用的 */
    --sv-font: 'SV RoundPix', 'Z Labs RoundPix 16px M CN', 'SV Fusion', 'Fusion Pixel 12px Mono latin', 'Microsoft YaHei', sans-serif;
    --sv-name-font: 'SV Fusion', 'Fusion Pixel 12px Mono latin', 'SV RoundPix', 'Z Labs RoundPix 16px M CN', sans-serif;
    /* 主题设置里选「普通字」时用的字体 */
    --sv-plain-font: 'Microsoft YaHei', 'PingFang SC', 'Noto Sans SC', sans-serif;
    --sv-name-size: 24px;

    --st-mes-padding-inline: 10px;
    --st-mes-padding-block: 2px;
    --st-mes-line-height: 1.75;   /* 16px 字 → 28px 一行，整数像素 */
}

/* ===== 母版 ===== */
:root {
    --mainFontSize: calc(var(--fontScale, 1) * 16px);
    --mainFontFamily: var(--sv-font);

    --sv-p: var(--sv-px);
    --sv-a: var(--sv-ava);
    --sv-fw: calc(var(--sv-p) * 6);                        /* 框的总宽：描边 + 五道木条 */
    --sv-abox: calc(var(--sv-a) + var(--sv-p) * 8);       /* 头像框（衬纸 + 深色细边）的边长，不含外面三圈 */
    --sv-col: calc(var(--sv-a) + var(--sv-p) * 16 + 36px); /* 木板那一栏 */
    --sv-sh: calc(var(--sv-p) * 16);                       /* 卷轴名牌的高度（含两头纸筒伸出来的那一格） */

    --sv-ink: var(--SmartThemeBodyColor);
    --sv-paper: var(--SmartThemeBlurTintColor);
    --sv-accent: var(--SmartThemeUnderlineColor);
    --sv-slot: color-mix(in srgb, var(--sv-paper), var(--sv-frame-lo) 14%);
    --sv-ink-shadow: color-mix(in srgb, var(--sv-paper), var(--sv-frame-lo) 30%);

    --fx-ink: var(--sv-ink);
    --fx-meta: color-mix(in srgb, var(--sv-ink) 80%, var(--sv-paper));
    --fx-accent: var(--sv-accent);
    --fx-on-accent: var(--sv-scroll);
    --fx-hairline: color-mix(in srgb, var(--sv-ink) 30%, transparent);
    --fx-surface: var(--sv-slot);

    /* 四角各缺一格的像素方框 */
    --sv-notch: polygon(
        var(--sv-p) 0, calc(100% - var(--sv-p)) 0,
        calc(100% - var(--sv-p)) var(--sv-p), 100% var(--sv-p),
        100% calc(100% - var(--sv-p)), calc(100% - var(--sv-p)) calc(100% - var(--sv-p)),
        calc(100% - var(--sv-p)) 100%, var(--sv-p) 100%,
        var(--sv-p) calc(100% - var(--sv-p)), 0 calc(100% - var(--sv-p)),
        0 var(--sv-p), var(--sv-p) var(--sv-p));

    /* 细框（面板、弹窗、菜单、通知、输入区）：描边（border 给）| 亮橙 | 暗橙 | 纸边一道阴影；四角各缺一格（clip-path: var(--sv-notch)） */
    --sv-ring:
        inset 0 0 0 var(--sv-p) var(--sv-frame-br),
        inset 0 0 0 calc(var(--sv-p) * 2) var(--sv-frame-lo),
        inset 0 0 0 calc(var(--sv-p) * 3) var(--sv-paper-sh);
    --sv-tw: calc(var(--sv-p) * 4);   /* 细框总宽（含描边和阴影） */
    /* 小块（按钮、格子）：亮边在左上、暗边在右下 */
    --sv-bevel:
        inset var(--sv-p) var(--sv-p) 0 0 var(--sv-frame-hi),
        inset calc(var(--sv-p) * -1) calc(var(--sv-p) * -1) 0 0 var(--sv-frame-lo);
    /* 背包格子：左上一道内阴影 */
    --sv-sunk: inset var(--sv-p) var(--sv-p) 0 color-mix(in srgb, var(--sv-slot), var(--sv-outline) 20%);
    /* 纸贴着框的那一圈阴影；菜单米色牌子里的玫瑰色阴影 */
    --sv-paper-sh: color-mix(in srgb, var(--sv-paper), var(--sv-frame-lo) 45%);
    --sv-rosy: color-mix(in srgb, var(--sv-frame-lo), var(--sv-scroll) 30%);

    /* 纸：上下暗、中间亮，一级一级（不是平滑渐变） */
    --sv-paper-bands: linear-gradient(to bottom,
        color-mix(in srgb, var(--sv-c, var(--sv-paper)), var(--sv-frame) 16%) 0 9%,
        color-mix(in srgb, var(--sv-c, var(--sv-paper)), var(--sv-frame) 11%) 9% 21%,
        color-mix(in srgb, var(--sv-c, var(--sv-paper)), var(--sv-frame) 6%) 21% 34%,
        var(--sv-c, var(--sv-paper)) 34% 55%,
        color-mix(in srgb, var(--sv-c, var(--sv-paper)), var(--sv-frame) 4%) 55% 68%,
        color-mix(in srgb, var(--sv-c, var(--sv-paper)), var(--sv-frame) 9%) 68% 81%,
        color-mix(in srgb, var(--sv-c, var(--sv-paper)), var(--sv-frame) 14%) 81% 93%,
        color-mix(in srgb, var(--sv-c, var(--sv-paper)), var(--sv-frame) 19%) 93%);

    /* 纸上的小斑点（卷轴）：两层稀疏的点错开排。一个点 = 一格，在格子左上角 */
    --sv-speck-c: color-mix(in srgb, var(--sv-scroll), var(--sv-scroll-edge) 75%);
    --sv-speck:
        conic-gradient(at var(--sv-p) var(--sv-p), transparent 75%, var(--sv-speck-c) 0) calc(var(--sv-p) * 3) calc(var(--sv-p) * 2) / calc(var(--sv-p) * 17) calc(var(--sv-p) * 11),
        conic-gradient(at var(--sv-p) var(--sv-p), transparent 75%, var(--sv-speck-c) 0) calc(var(--sv-p) * 11) calc(var(--sv-p) * 7) / calc(var(--sv-p) * 23) calc(var(--sv-p) * 13),
        conic-gradient(at var(--sv-p) var(--sv-p), transparent 75%, var(--sv-speck-c) 0) calc(var(--sv-p) * 7) calc(var(--sv-p) * 4) / calc(var(--sv-p) * 29) calc(var(--sv-p) * 7);

    --sv-2: calc(var(--sv-p) * 2);
    --sv-3: calc(var(--sv-p) * 3);
    --sv-4: calc(var(--sv-p) * 4);
    --sv-5: calc(var(--sv-p) * 5);
    --sv-6: calc(var(--sv-p) * 6);

    /* 圆木（对话框的框）：横木从上往下、竖木从左往右都是 描边 | 深 | 亮/暗 | 暗/亮 | 深 | 描边（光从右上来） */
    --sv-hlog: linear-gradient(to bottom, var(--sv-outline) 0 var(--sv-p), var(--sv-frame-dk) var(--sv-p) var(--sv-2), var(--sv-frame-br) var(--sv-2) var(--sv-3), var(--sv-frame-lo) var(--sv-3) var(--sv-4), var(--sv-frame-dk) var(--sv-4) var(--sv-5), var(--sv-outline) var(--sv-5));
    --sv-vlog: linear-gradient(to right, var(--sv-outline) 0 var(--sv-p), var(--sv-frame-dk) var(--sv-p) var(--sv-2), var(--sv-frame-lo) var(--sv-2) var(--sv-3), var(--sv-frame-br) var(--sv-3) var(--sv-4), var(--sv-frame-dk) var(--sv-4) var(--sv-5), var(--sv-outline) var(--sv-5));
    --sv-fill-o: linear-gradient(var(--sv-outline) 0 0);
    --sv-fill-n: linear-gradient(var(--sv-nail) 0 0);

    /* 滑块的小钮：5×8 格的竖圆角小木块（四角空着），左暗、中间一道亮、右边橙 */
    --sv-knob:
        linear-gradient(var(--sv-frame-br) 0 0) var(--sv-2) var(--sv-2) / var(--sv-p) calc(var(--sv-p) * 4) no-repeat,
        linear-gradient(var(--sv-frame) 0 0) var(--sv-2) var(--sv-p) / var(--sv-2) calc(var(--sv-p) * 6) no-repeat,
        linear-gradient(var(--sv-frame-lo) 0 0) var(--sv-p) var(--sv-p) / var(--sv-p) calc(var(--sv-p) * 6) no-repeat,
        linear-gradient(var(--sv-outline) 0 0) 0 var(--sv-p) / 100% calc(var(--sv-p) * 6) no-repeat,
        linear-gradient(var(--sv-outline) 0 0) var(--sv-p) 0 / calc(var(--sv-p) * 3) 100% no-repeat;
}

@media (max-width: 1000px) {
    :root {
        --sv-p: var(--sv-px-m);
        --sv-a: var(--sv-ava-m);
        --sv-gap: 12px;
        --sv-sh: calc(var(--sv-p) * 20);
    }
}

/* ===== 聊天区：透出背景图（就是游戏里的田野） ===== */
#chat {
    background: none;
    padding-inline: 6px;
    padding-top: 14px;
}

#chat .mes {
    --sv-c: var(--SmartThemeBotMesBlurTintColor);
    position: relative;
    isolation: isolate;
    flex-shrink: 0;   /* #chat 是竖排 flex，不加这句手机上会被压扁 */
    margin: 0 0 var(--sv-gap);
    padding: var(--sv-fw);
    border: none;
    background: none;
}

/* 纸底：上下暗、中间亮的几级色带；贴着框一圈浅棕阴影 */
#chat .mes::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    background: var(--sv-paper-bands);
    box-shadow: inset 0 0 0 calc(var(--sv-fw) + var(--sv-p)) var(--sv-paper-sh);
}

/* 圆木框：四根木头盖在最上面（木板伸到框底下去）。竖木压着横木，横竖两头都伸出去两格，交接处一颗钉子。
 * 伪元素比消息大一圈（每边两格），所以下面的位置都是从伪元素的边算的 */
#chat .mes::after {
    content: '';
    position: absolute;
    inset: calc(var(--sv-p) * -2);
    z-index: 3;
    pointer-events: none;
    --sv-nails:
        var(--sv-fill-n) left var(--sv-4) top var(--sv-5) / var(--sv-p) var(--sv-p) no-repeat,
        var(--sv-fill-n) left var(--sv-4) bottom var(--sv-4) / var(--sv-p) var(--sv-p) no-repeat,
        var(--sv-fill-n) right var(--sv-5) top var(--sv-5) / var(--sv-p) var(--sv-p) no-repeat,
        var(--sv-fill-n) right var(--sv-5) bottom var(--sv-4) / var(--sv-p) var(--sv-p) no-repeat;
    --sv-posts:
        var(--sv-vlog) left var(--sv-2) top var(--sv-p) / var(--sv-6) calc(100% - var(--sv-2)) no-repeat,
        var(--sv-vlog) right var(--sv-2) top var(--sv-p) / var(--sv-6) calc(100% - var(--sv-2)) no-repeat,
        var(--sv-fill-o) left var(--sv-2) top 0 / var(--sv-6) 100% no-repeat,
        var(--sv-fill-o) right var(--sv-2) top 0 / var(--sv-6) 100% no-repeat;
    --sv-bars:
        var(--sv-hlog) left var(--sv-p) top var(--sv-2) / calc(100% - var(--sv-2)) var(--sv-6) no-repeat,
        var(--sv-hlog) left var(--sv-p) bottom var(--sv-2) / calc(100% - var(--sv-2)) var(--sv-6) no-repeat,
        var(--sv-fill-o) left 0 top var(--sv-2) / 100% var(--sv-6) no-repeat,
        var(--sv-fill-o) left 0 bottom var(--sv-2) / 100% var(--sv-6) no-repeat;
    background: var(--sv-nails), var(--sv-posts), var(--sv-bars);
}

#chat .mes_block {
    position: static;
    padding: 10px 4px 12px;
    min-width: 0;
}

#chat .mes .ch_name {
    position: static;
    min-height: 0;
    padding-inline: var(--st-mes-padding-inline);
}

/* 纸上的字带一道浅棕投影（游戏里的字就是这样） */
#chat .mes_text {
    font-weight: 400;
    overflow-x: auto;
    text-shadow: 1px 1px 0 var(--sv-ink-shadow);
}

#chat .mes .timestamp,
#chat .mes .mesIDDisplay,
#chat .mes .mes_timer,
#chat .mes .tokenCounterDisplay {
    font-family: var(--sv-name-font);
    font-size: 12px;
    color: var(--fx-meta);
    opacity: 1;
}

/* ---- 角色消息：纸板 + 木板 ---- */
#chat .mes:not([is_user="true"]) {
    display: grid;
    grid-template-columns: minmax(0, 1fr) var(--sv-col);
    align-items: start;
    min-height: calc(var(--sv-a) + var(--sv-fw) * 2 + 150px);
}

/* 电脑：纸板和木板之间还有一根竖木，同样伸出去、两头钉钉子（--sv-x = 它的右边到伪元素右边） */
@media (min-width: 1001px) {
    #chat .mes:not([is_user="true"])::after {
        --sv-x: calc(var(--sv-col) + var(--sv-fw) - var(--sv-6) + var(--sv-2));
        background:
            var(--sv-nails),
            var(--sv-fill-n) right calc(var(--sv-x) + var(--sv-3)) top var(--sv-5) / var(--sv-p) var(--sv-p) no-repeat,
            var(--sv-fill-n) right calc(var(--sv-x) + var(--sv-3)) bottom var(--sv-4) / var(--sv-p) var(--sv-p) no-repeat,
            var(--sv-vlog) right var(--sv-x) top var(--sv-p) / var(--sv-6) calc(100% - var(--sv-2)) no-repeat,
            var(--sv-fill-o) right var(--sv-x) top 0 / var(--sv-6) 100% no-repeat,
            var(--sv-posts), var(--sv-bars);
    }
}

#chat .mes:not([is_user="true"]) .mes_block { grid-column: 1; grid-row: 1; }

#chat .mes:not([is_user="true"]) .mesAvatarWrapper {
    grid-column: 2;
    grid-row: 1;
    align-self: stretch;
    position: relative;
    isolation: isolate;
    margin: calc(var(--sv-fw) * -1) calc(var(--sv-fw) * -1) calc(var(--sv-fw) * -1) 0;
    padding: calc(var(--sv-fw) + 16px) calc(var(--sv-fw) + 18px) calc(var(--sv-fw) + 10px) calc(var(--sv-6) + 18px);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    /* 木板。左边那根竖木由 .mes::after 画；这里在它左边压一道纸的阴影，木板上沿和左边各一道暗影 */
    background: var(--sv-wood);
    box-shadow:
        calc(var(--sv-p) * -1) 0 0 0 var(--sv-paper-sh),
        inset calc(var(--sv-6) + var(--sv-p)) calc(var(--sv-fw) + var(--sv-p)) 0 0 var(--sv-wood-lo);
}

/* 木纹：暗层（板缝、深纹、节疤）和亮层（浅纹）两张遮罩 */
#chat .mes:not([is_user="true"]) .mesAvatarWrapper::before,
#chat .mes:not([is_user="true"]) .mesAvatarWrapper::after {
    content: '';
    position: absolute;
    inset: 0 0 0 var(--sv-6);
    z-index: -1;
    pointer-events: none;
    -webkit-mask: var(--tex-wood-dark) 0 0 / calc(var(--sv-p) * var(--tex-wood-w)) calc(var(--sv-p) * var(--tex-wood-h)) repeat;
    mask: var(--tex-wood-dark) 0 0 / calc(var(--sv-p) * var(--tex-wood-w)) calc(var(--sv-p) * var(--tex-wood-h)) repeat;
    background: var(--sv-wood-lo);
}

#chat .mes:not([is_user="true"]) .mesAvatarWrapper::after {
    -webkit-mask-image: var(--tex-wood-light);
    mask-image: var(--tex-wood-light);
    background: var(--sv-wood-hi);
}

/* 头像：嵌在木板上的画框 —— 橙框一圈，里面一张旧纸：米白细边、纸上有浅色斑点，右上角卷起一个角、两边各有一处磨损 */
#chat .mes .mesAvatarWrapper .avatar,
body.big-avatars #chat .mes .mesAvatarWrapper .avatar,
body.square-avatars #chat .mes .mesAvatarWrapper .avatar,
body.rounded-avatars #chat .mes .mesAvatarWrapper .avatar {
    --sv-pspk: color-mix(in srgb, var(--sv-portrait-bg), var(--sv-scroll) 55%);
    width: var(--sv-a) !important;
    height: var(--sv-a) !important;
    flex: none;
    position: relative;
    box-sizing: content-box;
    padding: var(--sv-3);
    border-radius: 0 !important;
    background:
        conic-gradient(at var(--sv-p) var(--sv-p), transparent 75%, var(--sv-pspk) 0) calc(var(--sv-p) * 4) var(--sv-p) / calc(var(--sv-p) * 23) calc(var(--sv-p) * 13),
        conic-gradient(at var(--sv-p) var(--sv-p), transparent 75%, var(--sv-pspk) 0) calc(var(--sv-p) * 15) calc(var(--sv-p) * 2) / calc(var(--sv-p) * 31) calc(var(--sv-p) * 17),
        conic-gradient(at var(--sv-p) var(--sv-p), transparent 75%, var(--sv-pspk) 0) var(--sv-p) calc(var(--sv-p) * 9) / calc(var(--sv-p) * 19) calc(var(--sv-p) * 29),
        var(--sv-portrait-bg);
    /* 从外往里：描边 | 暗橙 | 亮橙 | 深（border）| 米白细边 | 纸；右下投影落在木板上 */
    border: var(--sv-p) solid var(--sv-frame-dk);
    box-shadow:
        inset 0 0 0 var(--sv-p) color-mix(in srgb, var(--sv-scroll), white 35%),
        0 0 0 var(--sv-p) var(--sv-frame-br),
        0 0 0 calc(var(--sv-p) * 2) var(--sv-frame-lo),
        0 0 0 calc(var(--sv-p) * 3) var(--sv-outline),
        var(--sv-p) var(--sv-p) 0 calc(var(--sv-p) * 3) var(--sv-ava-sh, var(--sv-wood-lo));
    margin: calc(var(--sv-p) * 4) 0 calc(var(--sv-p) * 4 + 74px);   /* 下面留给名牌 */
}

/* 纸的卷角和磨损：盖在图上面（右上角一个米白小三角 + 一道折痕；左边偏上、右边当中各一小截米白） */
#chat .mes .mesAvatarWrapper .avatar::after {
    --sv-cr: color-mix(in srgb, var(--sv-scroll), white 35%);
    --sv-fold: color-mix(in srgb, var(--sv-portrait-bg), var(--sv-frame-lo) 45%);
    content: '';
    position: absolute;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    background:
        linear-gradient(var(--sv-cr) 0 0) right var(--sv-p) top var(--sv-p) / var(--sv-3) var(--sv-p) no-repeat,
        linear-gradient(var(--sv-cr) 0 0) right var(--sv-p) top var(--sv-2) / var(--sv-2) var(--sv-p) no-repeat,
        linear-gradient(var(--sv-cr) 0 0) right var(--sv-p) top var(--sv-3) / var(--sv-p) var(--sv-p) no-repeat,
        linear-gradient(var(--sv-fold) 0 0) right var(--sv-4) top var(--sv-p) / var(--sv-p) var(--sv-p) no-repeat,
        linear-gradient(var(--sv-fold) 0 0) right var(--sv-3) top var(--sv-2) / var(--sv-p) var(--sv-p) no-repeat,
        linear-gradient(var(--sv-fold) 0 0) right var(--sv-2) top var(--sv-3) / var(--sv-p) var(--sv-p) no-repeat,
        linear-gradient(var(--sv-fold) 0 0) right var(--sv-p) top var(--sv-4) / var(--sv-p) var(--sv-p) no-repeat,
        linear-gradient(var(--sv-cr) 0 0) left var(--sv-p) top 18% / var(--sv-p) var(--sv-2) no-repeat,
        linear-gradient(var(--sv-fold) 0 0) left var(--sv-2) top 18% / var(--sv-p) var(--sv-p) no-repeat,
        linear-gradient(var(--sv-cr) 0 0) right var(--sv-p) top 52% / var(--sv-p) var(--sv-3) no-repeat,
        linear-gradient(var(--sv-fold) 0 0) right var(--sv-2) top 52% / var(--sv-p) var(--sv-2) no-repeat;
}

#chat .mes .mesAvatarWrapper .avatar img,
body.big-avatars #chat .mes .mesAvatarWrapper .avatar img,
body.square-avatars #chat .mes .mesAvatarWrapper .avatar img,
body.rounded-avatars #chat .mes .mesAvatarWrapper .avatar img {
    width: 100% !important;
    height: 100% !important;
    max-width: none;
    max-height: none;
    object-fit: cover;
    object-position: center top;
    border-radius: 0 !important;
    border: none;
    box-shadow: none;
    image-rendering: var(--sv-ava-render);
}

/* 卷轴名牌：名字在 DOM 里属于纸板，摆到头像下面去。
 * 纸身上下各让出一格，两头的纸筒比纸身高出一格（遮罩只留纸身那几行 + 两个纸筒那两列）。
 * 纸身：细描边、底边一道亮线、纸上小斑点，最下面一行是纸身的投影；纸筒：圆头，从外往里 亮 | 纸 | 暗 | 更暗，底下卷出一小截 */
#chat .mes:not([is_user="true"]) .name_text {
    position: absolute;
    z-index: 2;
    top: calc(var(--sv-fw) + 16px + var(--sv-p) * 8 + var(--sv-abox) + 12px);
    right: calc(var(--sv-fw) + 18px);
    width: calc(var(--sv-abox) + var(--sv-2));
    box-sizing: border-box;
    height: var(--sv-sh);
    padding: 0 calc(var(--sv-p) * 7) var(--sv-p);
    /* 不用 flex 居中：名字太长时 flex 会往两边溢出、省略号也不出来 */
    display: block;
    text-align: center;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    font-family: var(--sv-name-font);
    font-size: var(--sv-name-size);
    font-weight: 400;
    line-height: calc(var(--sv-sh) - var(--sv-p));
    color: var(--sv-ink);
    border: none;
    background:
        var(--sv-fill-o) left 0 top var(--sv-p) / 100% var(--sv-p) no-repeat,
        var(--sv-fill-o) left 0 bottom var(--sv-p) / 100% var(--sv-p) no-repeat,
        linear-gradient(var(--sv-name-sh, var(--sv-wood-lo)) 0 0) left 0 bottom 0 / 100% var(--sv-p) no-repeat,
        linear-gradient(color-mix(in srgb, var(--sv-scroll), white 60%) 0 0) left 0 bottom var(--sv-2) / 100% var(--sv-p) no-repeat,
        var(--sv-speck),
        linear-gradient(var(--sv-scroll) 0 0);
    -webkit-mask:
        linear-gradient(#000 0 0) 0 var(--sv-p) / 100% calc(100% - var(--sv-p)) no-repeat,
        linear-gradient(#000 0 0) left top / var(--sv-6) 100% no-repeat,
        linear-gradient(#000 0 0) right top / var(--sv-6) 100% no-repeat;
    mask:
        linear-gradient(#000 0 0) 0 var(--sv-p) / 100% calc(100% - var(--sv-p)) no-repeat,
        linear-gradient(#000 0 0) left top / var(--sv-6) 100% no-repeat,
        linear-gradient(#000 0 0) right top / var(--sv-6) 100% no-repeat;
    box-shadow: none;
    text-shadow: 1px 1px 0 var(--sv-scroll-edge);
}

#chat .mes:not([is_user="true"]) .name_text::before,
#chat .mes:not([is_user="true"]) .name_text::after {
    --sv-cr: color-mix(in srgb, var(--sv-scroll), white 60%);
    --sv-e2: color-mix(in srgb, var(--sv-scroll-edge), var(--sv-frame-lo) 30%);
    content: '';
    position: absolute;
    top: 0;
    bottom: 0;
    left: 0;
    width: var(--sv-6);
    background:
        var(--sv-fill-o) left 0 top var(--sv-2) / var(--sv-p) calc(100% - var(--sv-4)) no-repeat,
        var(--sv-fill-o) left var(--sv-p) top var(--sv-p) / var(--sv-p) var(--sv-p) no-repeat,
        var(--sv-fill-o) left var(--sv-p) bottom var(--sv-p) / var(--sv-p) var(--sv-p) no-repeat,
        var(--sv-fill-o) left var(--sv-2) top 0 / calc(100% - var(--sv-2)) var(--sv-p) no-repeat,
        var(--sv-fill-o) left var(--sv-2) bottom 0 / calc(100% - var(--sv-2)) var(--sv-p) no-repeat,
        linear-gradient(var(--sv-cr) 0 0) left var(--sv-2) bottom var(--sv-p) / var(--sv-2) var(--sv-p) no-repeat,
        linear-gradient(var(--sv-e2) 0 0) left var(--sv-3) bottom var(--sv-2) / var(--sv-p) var(--sv-p) no-repeat,
        linear-gradient(to right,
            transparent 0 var(--sv-p),
            var(--sv-cr) var(--sv-p) var(--sv-2),
            var(--sv-scroll) var(--sv-2) var(--sv-3),
            color-mix(in srgb, var(--sv-scroll), var(--sv-scroll-edge) 50%) var(--sv-3) var(--sv-4),
            var(--sv-scroll-edge) var(--sv-4) var(--sv-5),
            var(--sv-e2) var(--sv-5)) left 0 top var(--sv-p) / 100% calc(100% - var(--sv-2)) no-repeat;
}

#chat .mes:not([is_user="true"]) .name_text::after {
    left: auto;
    right: 0;
    transform: scaleX(-1);
}

/* 消息编号、耗时、字数：名牌下面的木板上，深色小字（浅色字在木头上对比度不够） */
#chat .mes:not([is_user="true"]) .mesIDDisplay,
#chat .mes:not([is_user="true"]) .mes_timer,
#chat .mes:not([is_user="true"]) .tokenCounterDisplay {
    color: color-mix(in srgb, var(--sv-outline), black 45%);
    text-shadow: 1px 1px 0 var(--sv-wood-hi);
}

/* ---- 默认排版「铺满」：不要木板那一栏。头像和名牌挂在纸的右上角（浮在右边），字绕着它走、下面铺满整张纸。
 * 主题设置里选「木板分栏」= 脚本给 <html> 写 data-sv-layout="board"，就是上面那一套 ---- */
html:not([data-sv-layout="board"]) #chat .mes:not([is_user="true"]) {
    --sv-ava-sh: var(--sv-paper-sh);
    --sv-name-sh: var(--sv-paper-sh);
}

html:not([data-sv-layout="board"]) #chat .mes:not([is_user="true"]) .mesAvatarWrapper::before,
html:not([data-sv-layout="board"]) #chat .mes:not([is_user="true"]) .mesAvatarWrapper::after {
    display: none;
}

html:not([data-sv-layout="board"]) #chat .mes:not([is_user="true"]) .mesIDDisplay,
html:not([data-sv-layout="board"]) #chat .mes:not([is_user="true"]) .mes_timer,
html:not([data-sv-layout="board"]) #chat .mes:not([is_user="true"]) .tokenCounterDisplay {
    color: var(--fx-meta);
    text-shadow: none;
}

@media (min-width: 1001px) {
    html:not([data-sv-layout="board"]) #chat .mes:not([is_user="true"]) {
        display: flow-root;
        min-height: 0;
    }

    html:not([data-sv-layout="board"]) #chat .mes:not([is_user="true"])::after {
        background: var(--sv-nails), var(--sv-posts), var(--sv-bars);
    }

    html:not([data-sv-layout="board"]) #chat .mes:not([is_user="true"]) .mesAvatarWrapper {
        float: right;
        position: relative;
        margin: calc(var(--sv-fw) * -1) calc(var(--sv-fw) * -1) 0 0;
        padding: calc(var(--sv-fw) + 16px) calc(var(--sv-fw) + 18px + var(--sv-p)) 6px 28px;
        background: none;
        box-shadow: none;
    }

    /* 字要绕着头像走：消息块和正文都不能自成一块（overflow 不是 visible 就会整块让到头像左边去） */
    html:not([data-sv-layout="board"]) #chat .mes:not([is_user="true"]) .mes_block,
    html:not([data-sv-layout="board"]) #chat .mes:not([is_user="true"]) .mes_text {
        overflow: visible;
    }

    html:not([data-sv-layout="board"]) #chat .mes:not([is_user="true"]) .mes_text table {
        display: block;
        max-width: 100%;
        overflow-x: auto;
    }

    /* 最后一条下面要放换回复的箭头：头像那一列也往下让出一截 */
    html:not([data-sv-layout="board"]) #chat .mes.last_mes:not([is_user="true"]) .mesAvatarWrapper {
        padding-bottom: calc(var(--sv-p) * 12 + 18px);
    }

    html:not([data-sv-layout="board"]) #chat .mes:not([is_user="true"]) .swipeRightBlock { right: calc(var(--sv-fw) + 6px); }
    html:not([data-sv-layout="board"]) #chat .mes:not([is_user="true"]) .swipe_left { right: calc(var(--sv-fw) + 6px + var(--sv-p) * 14 + 34px); }
    html.sv-gen:not([data-sv-layout="board"]) #chat .mes.last_mes:not([is_user="true"]) .mes_block::after {
        right: calc(var(--sv-fw) + 6px + var(--sv-p) * 12);
    }
}

@media (max-width: 1000px) {
    html:not([data-sv-layout="board"]) #chat .mes:not([is_user="true"]) .mesAvatarWrapper {
        padding-bottom: 4px;
        background: none;
        box-shadow: none;
    }
}

/* 「铺满」默认在头像那一角垫一块木板（电脑）：左边和下边一道描边 + 一道暗边，往左下落一格阴影在纸上，字绕着木板走。
 * 主题设置里选「铺满（不垫木板）」= data-sv-layout="plain"，就是上面那样头像直接贴在纸上 */
@media (min-width: 1001px) {
    html:not([data-sv-layout="board"], [data-sv-layout="plain"]) #chat .mes:not([is_user="true"]) {
        --sv-ava-sh: var(--sv-wood-lo);
        --sv-name-sh: var(--sv-wood-lo);
    }

    html:not([data-sv-layout="board"], [data-sv-layout="plain"]) #chat .mes:not([is_user="true"]) .mesAvatarWrapper {
        margin-left: 14px;
        margin-bottom: var(--sv-p);
        padding-bottom: calc(6px + var(--sv-3));
        background: var(--sv-wood);
        box-shadow:
            inset var(--sv-p) calc(var(--sv-p) * -1) 0 0 var(--sv-outline),
            inset var(--sv-2) calc(var(--sv-2) * -1) 0 0 var(--sv-wood-lo),
            calc(var(--sv-p) * -1) var(--sv-p) 0 0 var(--sv-paper-sh);
    }

    html:not([data-sv-layout="board"], [data-sv-layout="plain"]) #chat .mes:not([is_user="true"]) .mesAvatarWrapper::before,
    html:not([data-sv-layout="board"], [data-sv-layout="plain"]) #chat .mes:not([is_user="true"]) .mesAvatarWrapper::after {
        display: block;
        inset: 0 0 var(--sv-2) var(--sv-2);
    }

    html:not([data-sv-layout="board"], [data-sv-layout="plain"]) #chat .mes:not([is_user="true"]).last_mes .mesAvatarWrapper {
        padding-bottom: calc(var(--sv-p) * 15 + 18px);
    }

    html:not([data-sv-layout="board"], [data-sv-layout="plain"]) #chat .mes:not([is_user="true"]) .mesIDDisplay,
    html:not([data-sv-layout="board"], [data-sv-layout="plain"]) #chat .mes:not([is_user="true"]) .mes_timer,
    html:not([data-sv-layout="board"], [data-sv-layout="plain"]) #chat .mes:not([is_user="true"]) .tokenCounterDisplay {
        color: color-mix(in srgb, var(--sv-outline), black 45%);
        text-shadow: 1px 1px 0 var(--sv-wood-hi);
    }
}

/* ---- 换回复：两只大箭头 ---- */
#chat .mes .swipe_left,
#chat .mes .swipeRightBlock {
    position: absolute;
    z-index: 4;
    bottom: calc(var(--sv-fw) + 4px);
}

#chat .mes:not([is_user="true"]) .swipeRightBlock { right: calc(var(--sv-col) + var(--sv-fw) + 6px); }
#chat .mes:not([is_user="true"]) .swipe_left { right: calc(var(--sv-col) + var(--sv-fw) + 6px + var(--sv-p) * 14 + 34px); }
#chat .mes[is_user="true"] .swipeRightBlock { right: calc(var(--sv-fw) + 6px); }
#chat .mes[is_user="true"] .swipe_left { right: calc(var(--sv-fw) + 6px + var(--sv-p) * 14 + 34px); }

#chat .mes .swipeRightBlock {
    flex-direction: row-reverse;
    align-items: center;
    gap: 4px;
}

#chat .mes .swipe_left,
#chat .mes .swipe_right {
    width: calc(var(--sv-p) * 14);
    height: calc(var(--sv-p) * 12);
    margin: 0;
    opacity: 1;
    filter: none;
    font-size: var(--sv-p);   /* 下面的小图按 em 画，1em = 一个像素 */
    transition: transform 0.1s steps(2);
}

#chat .mes .swipe_right { position: relative; }

#chat .mes .swipe_left::before,
#chat .mes .swipe_right::before {
    content: '';
    position: absolute;
    left: -1em;
    top: -1em;
    width: 1em;
    height: 1em;
    box-shadow: var(--spr-arrow);
}

#chat .mes .swipe_left::before { box-shadow: var(--spr-arrow-flip); }

#chat .mes .swipe_right:hover { transform: translateX(var(--sv-p)); }
#chat .mes .swipe_left:hover { transform: translateX(calc(var(--sv-p) * -1)); }

#chat .mes .swipes-counter {
    font-family: var(--sv-name-font);
    font-size: 12px;
    color: var(--sv-ink);
    min-width: 30px;
}

#chat .mes.last_mes .mes_block { padding-bottom: calc(var(--sv-p) * 12 + 18px); }

/* ---- 用户消息：游戏里的「选项框」，前面一个小箭头 ---- */
#chat .mes[is_user="true"] {
    --sv-c: var(--SmartThemeUserMesBlurTintColor);
    display: block;
}

#chat .mes[is_user="true"] .mesAvatarWrapper { display: none; }

#chat .mes[is_user="true"] .mes_block {
    padding-left: 34px;
}

#chat .mes[is_user="true"] .mes_block::before {
    content: '';
    position: absolute;
    left: calc(var(--sv-fw) + 12px);
    top: calc(var(--sv-fw) + 44px);
    width: calc(var(--sv-p) * 4);
    height: calc(var(--sv-p) * 6);
    background: var(--sv-accent);
    clip-path: polygon(0 0, 33% 0, 33% 16.7%, 66% 16.7%, 66% 33.3%, 100% 33.3%, 100% 66.7%, 66% 66.7%, 66% 83.3%, 33% 83.3%, 33% 100%, 0 100%);
    animation: sv-nudge 1.2s steps(2, jump-none) infinite;
}

@keyframes sv-nudge {
    from { transform: translateX(0); }
    to { transform: translateX(var(--sv-p)); }
}

#chat .mes[is_user="true"] .name_text {
    font-family: var(--sv-name-font);
    font-size: 12px;
    color: var(--fx-meta);
}

body.reduced-motion #chat .mes[is_user="true"] .mes_block::before { animation: none; }

/* ---- 系统消息：只要纸和框 ---- */
#chat .mes[is_system="true"] .mesAvatarWrapper { display: none; }
#chat .mes[is_system="true"] { display: block; min-height: 0; }

/* ---- 正文四种标签 ---- */
.mes_text q {
    color: var(--SmartThemeQuoteColor);
    font-style: normal;
}

/* 像素字不能加粗（会糊成一团），加粗改成往右多描一像素 */
.mes_text strong,
.mes_text b {
    font-weight: 400;
    text-shadow: 1px 0 0 currentColor, 1px 1px 0 var(--sv-ink-shadow);
}

/* 像素字没有斜体，心理活动只用颜色区分 */
.mes_text em {
    color: var(--SmartThemeEmColor);
    font-style: normal;
}

.mes_text code {
    font-family: var(--sv-name-font);
    font-size: 12px;
    background: var(--sv-slot);
    box-shadow: var(--sv-sunk);
    border: none;
    border-radius: 0;
    padding: 0.2em 0.5em;
    color: var(--sv-ink);
    text-shadow: none;
}

.mes_text pre {
    background: var(--sv-slot);
    border: var(--sv-p) solid var(--sv-frame-lo);
    box-shadow: var(--sv-sunk);
    border-radius: 0;
    padding: 6px 0 0 6px;
}

.mes_text pre code {
    background: none;
    box-shadow: none;
    padding: 0;
}

.mes_text blockquote {
    border-left: calc(var(--sv-p) * 2) solid var(--sv-frame);
    margin-inline: 0;
    padding-left: 1em;
}

.mes_text hr {
    border: none;
    height: var(--sv-p);
    background: repeating-linear-gradient(to right, var(--sv-frame-lo) 0 calc(var(--sv-p) * 2), transparent calc(var(--sv-p) * 2) calc(var(--sv-p) * 4));
}

/* ---- 正文里别的元素：标题、列表、表格、折叠、引用块 ---- */
/* 像素字不加粗；一级标题放大两倍（整数倍才清楚），二级下面一道虚线，三级以下用绿色 */
.mes_text h1,
.mes_text h2,
.mes_text h3,
.mes_text h4,
.mes_text h5,
.mes_text h6,
.mes_reasoning h1,
.mes_reasoning h2,
.mes_reasoning h3,
.mes_reasoning h4,
.mes_reasoning h5,
.mes_reasoning h6 {
    font-weight: 400;
    font-size: var(--mainFontSize);
    line-height: 1.75;
    margin: 0.6em 0 0.3em;
    color: var(--sv-ink);
    text-shadow: 1px 0 0 currentColor, 1px 1px 0 var(--sv-ink-shadow);
}

.mes_text h1,
.mes_reasoning h1 {
    font-size: calc(var(--mainFontSize) * 2);
    line-height: 1.25;
    text-shadow: 2px 2px 0 var(--sv-ink-shadow);
}

.mes_text h2,
.mes_reasoning h2 {
    padding-bottom: var(--sv-p);
    background: repeating-linear-gradient(to right, var(--sv-frame-lo) 0 var(--sv-2), transparent var(--sv-2) var(--sv-4)) left bottom / 100% var(--sv-p) no-repeat;
}

.mes_text h3,
.mes_text h4,
.mes_text h5,
.mes_text h6,
.mes_reasoning h3,
.mes_reasoning h4,
.mes_reasoning h5,
.mes_reasoning h6 {
    color: var(--SmartThemeUnderlineColor);
}

/* 列表：小方块 / 数字都是橙木色 */
.mes_text ul,
.mes_reasoning ul { list-style-type: square; }
.mes_text ul ul,
.mes_reasoning ul ul { list-style-type: '- '; }
.mes_text li::marker,
.mes_reasoning li::marker { color: var(--sv-frame-lo); }

/* 引用块：凹进去的一块背包格子，左边一道橙木（酒馆默认是一层黑色半透明底） */
.mes_text blockquote,
.mes_reasoning blockquote {
    background: var(--sv-slot);
    box-shadow: var(--sv-sunk);
    border-left: var(--sv-2) solid var(--sv-frame);
    margin: 0.5em 0;
    padding: 0.3em 1em;
}

/* 表格：表头是一条凸起的米色木牌，格子之间一格深色线 */
.mes_text table,
.mes_reasoning table {
    border-collapse: collapse;
    border: none;
}

.mes_text th,
.mes_text td,
.mes_reasoning th,
.mes_reasoning td {
    border: var(--sv-p) solid var(--sv-frame-lo);
    padding: 0.1em 0.7em;
}

.mes_text th,
.mes_reasoning th {
    font-weight: 400;
    background: var(--sv-scroll);
    border-bottom-color: var(--sv-outline);
}

/* 折叠：标题前面一只橙色小三角，打开时朝下 */
.mes_text details,
.mes_reasoning details {
    margin: 0.5em 0;
    padding-left: var(--sv-4);
    border-left: var(--sv-p) dashed var(--sv-frame-lo);
}

.mes_text details > summary,
.mes_reasoning details > summary {
    cursor: pointer;
    margin-left: calc(var(--sv-4) * -1 - var(--sv-p));
    padding-left: var(--sv-4);
    list-style: none;
    position: relative;
}

.mes_text details > summary::-webkit-details-marker { display: none; }

.mes_text details > summary::before,
.mes_reasoning details > summary::before {
    content: '';
    position: absolute;
    left: var(--sv-p);
    top: calc(50% - var(--sv-2));
    border: var(--sv-2) solid transparent;
    border-left: var(--sv-2) solid var(--sv-frame-lo);
}

.mes_text details[open] > summary::before,
.mes_reasoning details[open] > summary::before {
    left: 0;
    top: calc(50% - var(--sv-p));
    border: var(--sv-2) solid transparent;
    border-top: var(--sv-2) solid var(--sv-frame-lo);
}

/* ---- 思维链：标题是一块小橙木牌（像顶栏的按钮），点开下面是一块凹进去的格子，字小一号、颜色淡一档 ---- */
#chat .mes .mes_reasoning_header {
    background: var(--sv-frame);
    border: var(--sv-p) solid var(--sv-outline);
    border-radius: 0;
    box-shadow: var(--sv-bevel);
    clip-path: var(--sv-notch);
    color: var(--sv-outline);
    padding: var(--sv-p) calc(var(--sv-p) * 4 + 1em) var(--sv-p) calc(var(--sv-p) * 3);
    margin: 0.3em 0 0.5em;
    font-size: var(--mainFontSize);
}

#chat .mes .mes_reasoning_header:hover {
    background: color-mix(in srgb, var(--sv-frame), var(--sv-frame-hi) 35%);
}

#chat .mes .mes_reasoning_header_title,
#chat .mes .mes_reasoning_arrow {
    color: var(--sv-outline);
    opacity: 1;
}

#chat .mes .mes_reasoning {
    border: none;
    border-radius: 0;
    border-left: var(--sv-2) solid var(--sv-frame-lo);
    background: var(--sv-slot);
    box-shadow: var(--sv-sunk);
    padding: 0.4em 1em;
    color: var(--fx-meta);
    font-weight: 400;
}

/* ---- 藏起来的消息（眼睛按钮关掉、不发给 AI 的那些）：纸上一层斜着的浅棕细纹，字淡一档 ---- */
#chat .mes[is_system="true"]:not([ch_name="SillyTavern System"])::before {
    background:
        repeating-linear-gradient(135deg, transparent 0 var(--sv-3), color-mix(in srgb, var(--sv-paper-sh) 45%, transparent) var(--sv-3) var(--sv-4)),
        var(--sv-paper-bands);
}

#chat .mes[is_system="true"]:not([ch_name="SillyTavern System"]) .mes_text {
    color: var(--fx-meta);
}

#chat .mes .mes_ghost {
    color: var(--sv-frame-lo);
    opacity: 1;
}

/* ===== 背景：主题伴侣的脚本按主题设置给 <html> 写 data-sv-bg 和 --sv-bg-img（像素小图，放大时不糊）。
   选「酒馆里选的背景」时不写，酒馆自己的背景照常；聊天单独设的背景（#bg_custom）也照常盖在上面 ===== */
html[data-sv-bg] #bg1 {
    background-image: var(--sv-bg-img) !important;
    background-size: cover !important;
    background-position: center bottom !important;
    background-repeat: no-repeat !important;
    image-rendering: pixelated;
}

/* ===== 顶栏：一排凸起的橙色木块，打开的那块按下去、变亮 ===== */
#top-bar {
    background: none;
    backdrop-filter: none;
    box-shadow: none;
    border: none;
}

#top-settings-holder > .drawer > .drawer-toggle,
#top-settings-holder > .drawer > .drawer-icon {
    background: var(--sv-frame);
    border: var(--sv-p) solid var(--sv-outline);
    box-shadow: var(--sv-bevel);
    clip-path: var(--sv-notch);
    margin: 3px 3px calc(var(--sv-p) + 3px) 1px;
    padding: var(--sv-p) calc(var(--sv-p) * 2);
    transition: transform 0.1s steps(2), box-shadow 0.1s steps(2);
}

#top-settings-holder .drawer-icon {
    color: var(--sv-outline);
    opacity: 1;
    filter: none;
    text-shadow: 1px 1px 0 var(--sv-frame-hi);
}

#top-settings-holder > .drawer > .drawer-toggle:hover {
    background: color-mix(in srgb, var(--sv-frame), var(--sv-frame-hi) 35%);
}

#top-settings-holder > .drawer:has(.drawer-icon.openIcon) > .drawer-toggle {
    background: color-mix(in srgb, var(--sv-frame-hi), white 15%);
    box-shadow: inset var(--sv-p) var(--sv-p) 0 0 color-mix(in srgb, var(--sv-frame-hi), white 50%),
        inset calc(var(--sv-p) * -1) calc(var(--sv-p) * -1) 0 0 var(--sv-frame);
    transform: translate(var(--sv-p), var(--sv-p));
}

#top-settings-holder .drawer-icon.openIcon {
    color: var(--sv-outline);
}

/* ===== 图标：顶栏和输入栏的图标换成彩色像素画（12×12 格，一格 = --sv-p，深色描边；画在 tools/farm/sprites.mjs 的 ICONS，颜色走 --sv-* 变量） =====
   别的扩展加的图标不认识，照旧用原来的字体图标 */
#top-settings-holder .drawer-icon.fa-sliders { --sv-ico: var(--ico-sliders); }
#top-settings-holder .drawer-icon.fa-plug { --sv-ico: var(--ico-plug); }
#top-settings-holder .drawer-icon.fa-plug-circle-exclamation { --sv-ico: var(--ico-plugx); }
#top-settings-holder .drawer-icon.fa-font { --sv-ico: var(--ico-font); }
#top-settings-holder .drawer-icon.fa-book-atlas { --sv-ico: var(--ico-book); }
#top-settings-holder .drawer-icon.fa-user-cog { --sv-ico: var(--ico-usercog); }
#top-settings-holder .drawer-icon.fa-panorama { --sv-ico: var(--ico-panorama); }
#top-settings-holder .drawer-icon.fa-cubes { --sv-ico: var(--ico-cubes); }
#top-settings-holder .drawer-icon.fa-face-smile { --sv-ico: var(--ico-smile); }
#top-settings-holder .drawer-icon.fa-address-card { --sv-ico: var(--ico-card); }
#options_button { --sv-ico: var(--ico-bars); }
#extensionsMenuButton { --sv-ico: var(--ico-wand); }
#send_but { --sv-ico: var(--ico-send); }
#mes_continue { --sv-ico: var(--ico-next); }
#mes_impersonate { --sv-ico: var(--ico-secret); }
#mes_stop .fa-circle-stop { --sv-ico: var(--ico-stop); }

#top-settings-holder .drawer-icon.fa-sliders::before,
#top-settings-holder .drawer-icon.fa-plug::before,
#top-settings-holder .drawer-icon.fa-plug-circle-exclamation::before,
#top-settings-holder .drawer-icon.fa-font::before,
#top-settings-holder .drawer-icon.fa-book-atlas::before,
#top-settings-holder .drawer-icon.fa-user-cog::before,
#top-settings-holder .drawer-icon.fa-panorama::before,
#top-settings-holder .drawer-icon.fa-cubes::before,
#top-settings-holder .drawer-icon.fa-face-smile::before,
#top-settings-holder .drawer-icon.fa-address-card::before,
:is(#options_button, #extensionsMenuButton, #send_but, #mes_continue, #mes_impersonate, #mes_stop .fa-circle-stop)::before {
    content: '' !important;
    display: block;
    font-size: var(--sv-p);
    width: 12em;
    height: 12em;
    margin: auto;
    background: var(--sv-ico);
}

#top-settings-holder .drawer-icon.fa-sliders,
#top-settings-holder .drawer-icon.fa-plug,
#top-settings-holder .drawer-icon.fa-plug-circle-exclamation,
#top-settings-holder .drawer-icon.fa-font,
#top-settings-holder .drawer-icon.fa-book-atlas,
#top-settings-holder .drawer-icon.fa-user-cog,
#top-settings-holder .drawer-icon.fa-panorama,
#top-settings-holder .drawer-icon.fa-cubes,
#top-settings-holder .drawer-icon.fa-face-smile,
#top-settings-holder .drawer-icon.fa-address-card {
    text-shadow: none;
    width: auto;
}

/* 顶栏图标 12 格高：木块的上下内边距收掉，顶栏加高到放得下整块木块（描边 2 格 + 图标 12 格 + 底下一格影子 + 上下各 3px） */
:root {
    --topBarBlockSize: calc(var(--sv-p) * 15 + 6px);
}

#top-settings-holder {
    height: var(--topBarBlockSize);
}

#top-settings-holder > .drawer > .drawer-toggle,
#top-settings-holder > .drawer > .drawer-icon {
    margin-top: 3px;
}

#top-settings-holder > .drawer > .drawer-toggle:has(.drawer-icon:is(.fa-sliders, .fa-plug, .fa-plug-circle-exclamation, .fa-font, .fa-book-atlas, .fa-user-cog, .fa-panorama, .fa-cubes, .fa-face-smile, .fa-address-card)) {
    padding-block: 0;
}

/* 输入栏的图标小一号（一格 2px，手机上照样是 --sv-p） */
@media (min-width: 1001px) {
    :is(#options_button, #extensionsMenuButton, #send_but, #mes_continue, #mes_impersonate, #mes_stop .fa-circle-stop)::before {
        font-size: 2px;
    }
}

/* ===== 面板：细框（描边 | 亮橙 | 暗橙 | 纸边阴影），四角各缺一格 ===== */
.drawer-content,
#left-nav-panel,
#right-nav-panel,
.popup {
    background: var(--sv-paper);
    border: var(--sv-p) solid var(--sv-outline);
    border-radius: 0;
    box-shadow: var(--sv-ring);
    clip-path: var(--sv-notch);
    backdrop-filter: none;
    color: var(--sv-ink);
}

.drawer-content,
#left-nav-panel,
#right-nav-panel {
    padding: calc(var(--sv-tw) + 6px);
}

/* 左边面板（AI 设置、预设）：聊天区两边的空白太窄时，放宽到 --sv-lpanel，盖住聊天区一点；
 * 这时面板从顶栏下面开始，顶栏那一排按钮（包括「AI 响应配置」）照样点得到 */
@media (min-width: 1001px) {
    #left-nav-panel {
        --sv-lgut: calc((100dvw - var(--sheldWidth)) / 2);
        --sv-ltop: clamp(0px, (var(--sv-lpanel) - var(--sv-lgut)) * 1000, var(--topBarBlockSize, 40px));
        width: max(calc(var(--sv-lgut) - 1px), var(--sv-lpanel));
        top: var(--sv-ltop);
        max-height: calc(100dvh - var(--sv-ltop));
    }

    #left-nav-panel.openDrawer { height: calc(100dvh - var(--sv-ltop)); }
}

.drawer-content h3,
.drawer-content h4,
.inline-drawer-header b,
.popup h3 {
    font-family: var(--sv-name-font);
    font-weight: 400;
}

/* 分组标题：一条卷轴 */
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    background: linear-gradient(to bottom,
        color-mix(in srgb, var(--sv-scroll), white 40%) 0 20%,
        var(--sv-scroll) 20% 72%,
        var(--sv-scroll-edge) 72%);
    border: var(--sv-p) solid var(--sv-outline);
    border-inline-width: calc(var(--sv-p) * 3);
    border-radius: 0;
    color: var(--sv-ink);
    text-shadow: none;
}

/* 悬停：酒馆默认整块 brightness(150%)，米色卷轴一提亮就白得刺眼。改成卷轴往亮橙走一点 */
#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover,
.standoutHeader.inline-drawer-header:hover {
    filter: none;
    background: linear-gradient(to bottom,
        color-mix(in srgb, var(--sv-scroll), var(--sv-frame-hi) 25%) 0 20%,
        color-mix(in srgb, var(--sv-scroll), var(--sv-frame-hi) 45%) 20% 72%,
        var(--sv-scroll-edge) 72%);
}

.drawer-content h2,
#rm_button_selected_ch h2 {
    color: var(--sv-ink);
    opacity: 1;
}

/* 酒馆给小字、说明、角色名按钮默认加了 50%~70% 透明，在纸上太淡：改成实色次要字 */
small,
.text_muted,
#rm_button_selected_ch {
    opacity: 1;
}

small,
.text_muted {
    color: var(--fx-meta);
}

.menu_button small {
    color: inherit;
}

#chat .mes .swipes-counter,
#version_display {
    opacity: 1 !important;   /* 酒馆用行内样式淡出到 0.7 */
}

/* 输入框、下拉：背包格子 */
.text_pole,
select,
textarea:not(#send_textarea) {
    background-color: var(--sv-slot);
    box-shadow: var(--sv-sunk);
    border: var(--sv-p) solid var(--sv-frame-lo);
    border-radius: 0;
    clip-path: var(--sv-notch);
    color: var(--sv-ink);
}

select option {
    background: var(--sv-paper);
    color: var(--sv-ink);
}

/* 酒馆很多地方平时压暗、悬停 / 选中时 filter: brightness(1.2~1.5) 提亮，米色和亮橙一提就发白：一律去掉，
   小图标按钮（右边面板顶上那排、图片翻页）平时实色，悬停 / 选中换成橙木色 */
.right_menu_button,
.right_menu_button:hover,
.right_menu_button.active,
.selected-right-tab,
.neo-range-slider:hover,
input[type="range"]:hover,
a:hover,
.ui-slider-handle,
.ui-slider-handle.ui-state-active,
.popup-controls .menu_button:hover:focus-visible {
    filter: none;
}

.right_menu_button:hover,
.right_menu_button.active,
.selected-right-tab {
    color: var(--sv-frame-lo);
}

/* 按钮：凸起的小橙块 */
.menu_button {
    background: var(--sv-frame);
    border: var(--sv-p) solid var(--sv-outline);
    border-radius: 0;
    box-shadow: var(--sv-bevel);
    color: var(--sv-outline);
    padding-inline: calc(var(--sv-p) * 4);
    filter: none;
    opacity: 1;
    text-shadow: 1px 1px 0 var(--sv-frame-hi);
    clip-path: var(--sv-notch);
}

.menu_button:not(.disabled):not([disabled]):hover,
.menu_button:not(.disabled):not([disabled]).active {
    background: color-mix(in srgb, var(--sv-frame), var(--sv-frame-hi) 35%);
}

.menu_button:active {
    transform: translateY(var(--sv-p));
}

/* 弹窗的「确定」：绿色木块（游戏里的确定钮就是绿的） */
.popup .menu_button.popup-button-ok:not(.disabled):not([disabled]),
.popup .menu_button.popup-button-ok:not(.disabled):not([disabled]):hover {
    background: var(--sv-accent);
    border-color: var(--sv-outline);
    color: var(--sv-scroll);
    text-shadow: 1px 1px 0 var(--sv-outline);
    box-shadow:
        inset var(--sv-p) var(--sv-p) 0 0 var(--sv-accent-hi),
        inset calc(var(--sv-p) * -1) calc(var(--sv-p) * -1) 0 0 color-mix(in srgb, var(--sv-accent), var(--sv-outline) 45%);
}

.popup .menu_button.popup-button-ok:not(.disabled):not([disabled]):hover {
    background: color-mix(in srgb, var(--sv-accent), var(--sv-accent-hi) 30%);
}

/* 键盘选中：游戏里的红框（画在里面，外面会被缺角裁掉） */
.popup .popup-controls .menu_button:focus-visible {
    outline: none;
    box-shadow: inset 0 0 0 var(--sv-p) var(--sv-select) !important;
}

/* ---- 勾选框：深色细框，里面左上一道阴影、右下往外投一道影；勾是绿色的像素勾 ---- */
input[type="checkbox"] {
    --sv-cb-sh: color-mix(in srgb, var(--sv-paper), var(--sv-outline) 35%);
    width: calc(var(--sv-p) * 8);
    height: calc(var(--sv-p) * 8);
    min-width: calc(var(--sv-p) * 8);
    outline: none;
    border: var(--sv-p) solid var(--sv-outline);
    border-radius: 0;
    background-color: var(--sv-paper);
    box-shadow:
        inset var(--sv-p) var(--sv-p) 0 var(--sv-cb-sh),
        var(--sv-p) var(--sv-p) 0 0 var(--sv-cb-sh);
    font-size: var(--sv-p);
}

input[type="checkbox"]:checked {
    border-color: var(--sv-outline);
    background-color: var(--sv-paper);   /* shared/st-fixes 会整块涂强调色 */
}

/* 勾：6×5 格的像素小图，放在 6 格见方的框里（下面空半格） */
input[type="checkbox"]::before {
    position: absolute;
    left: -1em;
    top: -0.5em;
    width: 1em;
    height: 1em;
    clip-path: none;
    box-shadow: var(--spr-tick);
    transform-origin: 3.5em 3em;
    transition: transform 0.1s steps(2);
}

/* ---- 滑块：一根没有框的细线（下面一道浅影），小钮是竖着的圆角小木块 ---- */
input[type="range"],
.neo-range-slider {
    -webkit-appearance: none !important;
    appearance: none !important;
    height: calc(var(--sv-p) * 8) !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    filter: none !important;
    background: linear-gradient(to bottom,
        transparent 0 calc(50% - var(--sv-p)),
        var(--sv-frame-dk) calc(50% - var(--sv-p)) calc(50% + var(--sv-p)),
        var(--sv-paper-sh) calc(50% + var(--sv-p)) calc(50% + var(--sv-2)),
        transparent calc(50% + var(--sv-2))) !important;
    background-size: 100% 100% !important;
}

input[type="range"]::-webkit-slider-runnable-track {
    height: calc(var(--sv-p) * 8);
    background: transparent;
    border: none;
    box-shadow: none;
}

input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: calc(var(--sv-p) * 5);
    height: calc(var(--sv-p) * 8);
    margin-top: 0;
    border: none;
    border-radius: 0;
    background: var(--sv-knob);
    box-shadow: none;
}

input[type="range"]::-moz-range-track {
    height: calc(var(--sv-p) * 8);
    background: transparent;
    border: none;
}

input[type="range"]::-moz-range-thumb {
    width: calc(var(--sv-p) * 5);
    height: calc(var(--sv-p) * 8);
    border: none;
    border-radius: 0;
    background: var(--sv-knob);
}

/* 滑块旁边的数字框：和输入框一样的背包格子 */
.range-block-counter input,
.neo-range-input {
    background-color: var(--sv-slot);
    border: var(--sv-p) solid var(--sv-frame-lo);
    border-radius: 0;
    box-shadow: var(--sv-sunk);
    clip-path: var(--sv-notch);
    color: var(--sv-ink);
    font-family: var(--sv-name-font);
}

input[type="radio"] {
    accent-color: var(--sv-accent);
}

/* ===== 电脑滚动条：深色细框里一道灰米色的槽（右边一道暗），滑块是橙色木块：左、下暗，上、右亮，四角空出一格 ===== */
@media (hover: hover) and (pointer: fine) {
    ::-webkit-scrollbar {
        width: 18px;
        height: 18px;
    }

    ::-webkit-scrollbar-track {
        background: linear-gradient(to right,
            var(--sv-outline) 0 3px, var(--sv-track) 3px 12px,
            color-mix(in srgb, var(--sv-track), var(--sv-outline) 18%) 12px 15px, var(--sv-outline) 15px);
    }

    ::-webkit-scrollbar-track:horizontal {
        background: linear-gradient(to bottom,
            var(--sv-outline) 0 3px, var(--sv-track) 3px 12px,
            color-mix(in srgb, var(--sv-track), var(--sv-outline) 18%) 12px 15px, var(--sv-outline) 15px);
    }

    ::-webkit-scrollbar-thumb:vertical,
    ::-webkit-scrollbar-thumb:horizontal {
        --sv-sbf: var(--sv-frame);
        --sv-sbh: color-mix(in srgb, var(--sv-frame), var(--sv-scroll) 50%);
        border: none;
        border-radius: 0;
        box-shadow: none;
        background:
            linear-gradient(var(--sv-outline) 0 0) 3px 0 / calc(100% - 6px) 3px no-repeat,
            linear-gradient(var(--sv-outline) 0 0) 3px 100% / calc(100% - 6px) 3px no-repeat,
            linear-gradient(var(--sv-outline) 0 0) 0 3px / 3px calc(100% - 6px) no-repeat,
            linear-gradient(var(--sv-outline) 0 0) 100% 3px / 3px calc(100% - 6px) no-repeat,
            linear-gradient(var(--sv-frame-lo) 0 0) 3px 3px / 3px calc(100% - 6px) no-repeat,
            linear-gradient(var(--sv-frame-lo) 0 0) 3px calc(100% - 3px) / calc(100% - 6px) 3px no-repeat,
            linear-gradient(var(--sv-sbh) 0 0) calc(100% - 3px) 3px / 3px calc(100% - 6px) no-repeat,
            linear-gradient(var(--sv-sbh) 0 0) 3px 3px / calc(100% - 6px) 3px no-repeat,
            linear-gradient(var(--sv-sbf) 0 0) 3px 3px / calc(100% - 6px) calc(100% - 6px) no-repeat;
    }

    ::-webkit-scrollbar-thumb:vertical:hover,
    ::-webkit-scrollbar-thumb:horizontal:hover {
        --sv-sbf: color-mix(in srgb, var(--sv-frame), var(--sv-frame-hi) 40%);
    }

    ::-webkit-scrollbar-corner { background: transparent; }
}

/* ===== 菜单（≡、魔杖）：一块块偏红的旧木板摞起来，板和板之间一道深缝；每块板上凹进去一块米黄牌子（深色细边，左上两道阴影、四角圆一格） ===== */
#options .options-content,
#extensionsMenu {
    background: var(--sv-outline);
    border: var(--sv-p) solid var(--sv-outline);
    border-radius: 0;
    box-shadow: none;
    clip-path: var(--sv-notch);
    padding: 0;
    backdrop-filter: none;
}

#options .options-content a,
#extensionsMenu > .extension_container > div,
#extensionsMenu > div.list-group-item {
    --sv-pq: var(--sv-plaque);
    margin: 0;
    padding: calc(var(--sv-p) * 6) calc(var(--sv-p) * 6 + 10px) calc(var(--sv-p) * 5);
    border: none;
    border-top: var(--sv-2) solid var(--sv-outline);
    border-radius: 0;
    background:
        linear-gradient(var(--sv-plaque-edge) 0 0) left var(--sv-6) top var(--sv-6) / var(--sv-p) var(--sv-p) no-repeat,
        linear-gradient(var(--sv-plaque-edge) 0 0) right var(--sv-5) top var(--sv-6) / var(--sv-p) var(--sv-p) no-repeat,
        linear-gradient(var(--sv-plaque-edge) 0 0) left var(--sv-6) bottom var(--sv-5) / var(--sv-p) var(--sv-p) no-repeat,
        linear-gradient(var(--sv-plaque-edge) 0 0) right var(--sv-5) bottom var(--sv-5) / var(--sv-p) var(--sv-p) no-repeat,
        var(--sv-pq);
    /* 从外往里：板上沿一道亮线 | 木板 | 牌子的深色细边 | 左上一道深影、一道浅影 | 右下一道浅影 */
    box-shadow:
        inset 0 var(--sv-p) 0 0 var(--sv-plank-hi),
        inset 0 0 0 var(--sv-3) var(--sv-plank),
        inset 0 0 0 var(--sv-4) var(--sv-outline),
        inset var(--sv-5) var(--sv-5) 0 0 var(--sv-plank-lo),
        inset var(--sv-6) var(--sv-6) 0 0 var(--sv-plaque-edge),
        inset calc(var(--sv-5) * -1) calc(var(--sv-5) * -1) 0 0 var(--sv-plaque-edge);
    color: var(--sv-ink);
    opacity: 1;
}

/* 木板上的纹：上下两条木板边上一截一截的深纹和亮纹 */
#options .options-content a,
#extensionsMenu > .extension_container > div,
#extensionsMenu > div.list-group-item {
    position: relative;
}

#options .options-content a::after,
#extensionsMenu > .extension_container > div::after,
#extensionsMenu > div.list-group-item::after {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
    background:
        repeating-linear-gradient(to right,
            transparent 0 calc(var(--sv-p) * 9), var(--sv-plank-lo) calc(var(--sv-p) * 9) calc(var(--sv-p) * 13),
            transparent calc(var(--sv-p) * 13) calc(var(--sv-p) * 15), var(--sv-plank-lo) calc(var(--sv-p) * 15) calc(var(--sv-p) * 16),
            transparent calc(var(--sv-p) * 16) calc(var(--sv-p) * 31), var(--sv-plank-hi) calc(var(--sv-p) * 31) calc(var(--sv-p) * 34),
            transparent calc(var(--sv-p) * 34) calc(var(--sv-p) * 47)) left 0 top var(--sv-2) / 100% var(--sv-p) no-repeat,
        repeating-linear-gradient(to right,
            transparent 0 calc(var(--sv-p) * 4), var(--sv-plank-hi) calc(var(--sv-p) * 4) calc(var(--sv-p) * 6),
            transparent calc(var(--sv-p) * 6) calc(var(--sv-p) * 22), var(--sv-plank-lo) calc(var(--sv-p) * 22) calc(var(--sv-p) * 27),
            transparent calc(var(--sv-p) * 27) calc(var(--sv-p) * 41)) left 0 bottom var(--sv-p) / 100% var(--sv-p) no-repeat;
}

#options .options-content a:first-of-type,
#extensionsMenu > :first-child,
#extensionsMenu > :first-child > div:first-child {
    border-top: none;
}

#options .options-content a:hover,
#extensionsMenu > .extension_container > div:hover,
#extensionsMenu > div.list-group-item:hover {
    --sv-pq: color-mix(in srgb, var(--sv-plaque), var(--sv-frame-hi) 45%);
}

#options .options-content hr { display: none; }

#options .options-content a *,
#extensionsMenu .list-group-item * {
    color: var(--sv-ink);
    opacity: 1;
}

/* ===== 角色列表、人设列表：一行一张卡，里面一道细双线；头像是人物卡（深色描边、四角缺一格） ===== */
#rm_print_characters_block .character_select,
#rm_print_characters_block .group_select,
#user_avatar_block .avatar-container {
    margin: 0 0 calc(var(--sv-p) * 2);
    padding: 8px;
    border: var(--sv-p) solid var(--sv-frame-lo);
    border-radius: 0;
    background: color-mix(in srgb, var(--sv-paper), white 22%);
    box-shadow:
        inset 0 0 0 var(--sv-p) color-mix(in srgb, var(--sv-paper), white 60%),
        inset 0 0 0 calc(var(--sv-p) + 1px) var(--sv-frame-lo);
    clip-path: var(--sv-notch);
    opacity: 1;
}

#rm_print_characters_block .character_select:hover,
#rm_print_characters_block .group_select:hover,
#user_avatar_block .avatar-container:hover {
    background: color-mix(in srgb, var(--sv-paper), var(--sv-frame-hi) 25%);
}

/* 选中的那张深一档 */
#user_avatar_block .avatar-container.selected,
#rm_print_characters_block .character_select.selected {
    background: color-mix(in srgb, var(--sv-paper), var(--sv-frame) 32%);
    border-color: var(--sv-outline);
}

/* 人物卡：深色细描边，里面一圈深浅不匀的旧木头色，四角各缺一格、内角各一颗深色点（一格 = --sv-card-px，比别处细） */
#rm_print_characters_block .avatar,
#user_avatar_block .avatar,
#HotSwapWrapper .avatar,
#avatar_div_div {
    --c: var(--sv-card-px);
    border-radius: 0 !important;
    border: var(--c) solid var(--sv-card-dk);
    padding: var(--c);
    clip-path: polygon(
        var(--c) 0, calc(100% - var(--c)) 0, calc(100% - var(--c)) var(--c), 100% var(--c),
        100% calc(100% - var(--c)), calc(100% - var(--c)) calc(100% - var(--c)), calc(100% - var(--c)) 100%, var(--c) 100%,
        var(--c) calc(100% - var(--c)), 0 calc(100% - var(--c)), 0 var(--c), var(--c) var(--c));
    box-shadow: none;
    background:
        linear-gradient(var(--sv-card-dk) 0 0) left top / var(--c) var(--c) no-repeat padding-box,
        linear-gradient(var(--sv-card-dk) 0 0) right top / var(--c) var(--c) no-repeat padding-box,
        linear-gradient(var(--sv-card-dk) 0 0) left bottom / var(--c) var(--c) no-repeat padding-box,
        linear-gradient(var(--sv-card-dk) 0 0) right bottom / var(--c) var(--c) no-repeat padding-box,
        repeating-linear-gradient(to bottom,
            var(--sv-card) 0 calc(var(--c) * 5), var(--sv-card-dk) calc(var(--c) * 5) calc(var(--c) * 6),
            var(--sv-card) calc(var(--c) * 6) calc(var(--c) * 11), var(--sv-card-hi) calc(var(--c) * 11) calc(var(--c) * 13)) left top / var(--c) 100% no-repeat padding-box,
        repeating-linear-gradient(to top,
            var(--sv-card) 0 calc(var(--c) * 3), var(--sv-card-hi) calc(var(--c) * 3) calc(var(--c) * 5),
            var(--sv-card) calc(var(--c) * 5) calc(var(--c) * 10), var(--sv-card-dk) calc(var(--c) * 10) calc(var(--c) * 11)) right top / var(--c) 100% no-repeat padding-box,
        repeating-linear-gradient(to right,
            var(--sv-card) 0 calc(var(--c) * 7), var(--sv-card-hi) calc(var(--c) * 7) calc(var(--c) * 9),
            var(--sv-card) calc(var(--c) * 9) calc(var(--c) * 15), var(--sv-card-dk) calc(var(--c) * 15) calc(var(--c) * 16),
            var(--sv-card) calc(var(--c) * 16) calc(var(--c) * 21)) padding-box;
}

#rm_print_characters_block .avatar img,
#user_avatar_block .avatar img,
#HotSwapWrapper .avatar img {
    display: block;
    width: 100% !important;
    height: 100% !important;
    object-fit: cover;
}

#rm_print_characters_block .avatar img,
#user_avatar_block .avatar img,
#HotSwapWrapper .avatar img,
#avatar_div_div img {
    border-radius: 0 !important;
    border: none;
    image-rendering: var(--sv-ava-render);
}

#rm_print_characters_block .ch_name,
#user_avatar_block .ch_name {
    font-family: var(--sv-name-font);
    color: var(--sv-ink);
}

#rm_print_characters_block .ch_description,
#user_avatar_block .ch_description {
    color: var(--fx-meta);
    opacity: 1;
}

/* ===== 通知：左边一个图标小方框，右边一块文字框 ===== */
#toast-container > .toast {
    position: relative;
    isolation: isolate;
    overflow: visible;
    margin-left: 62px;
    padding: calc(var(--sv-tw) + 8px) calc(var(--sv-tw) + 26px) calc(var(--sv-tw) + 8px) calc(var(--sv-tw) + 10px);
    width: 320px;
    line-height: 1.5;
    background-color: transparent !important;
    background-image: none !important;
    border: none;
    border-radius: 0;
    box-shadow: none;
    color: var(--sv-ink);
    font-family: var(--sv-font);
    opacity: 1;
}

/* 文字框画在伪元素上（缺角要裁，左边的图标框不能跟着被裁） */
#toast-container > .toast::after {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    background: var(--sv-paper-bands);
    border: var(--sv-p) solid var(--sv-outline);
    box-shadow:
        inset 0 0 0 var(--sv-p) var(--sv-frame),
        inset 0 0 0 var(--sv-2) var(--sv-frame-lo),
        inset 0 0 0 var(--sv-3) var(--sv-outline),
        inset 0 var(--sv-4) 0 0 var(--sv-paper-sh);
    clip-path: var(--sv-notch);
}

#toast-container > .toast::before {
    content: '!';
    position: absolute;
    left: -62px;
    top: 50%;
    transform: translateY(-50%);
    width: 54px;
    height: 54px;
    box-sizing: border-box;
    display: grid;
    place-items: center;
    border: var(--sv-p) solid var(--sv-outline);
    background: var(--sv-scroll);
    box-shadow:
        inset 0 0 0 var(--sv-p) var(--sv-frame),
        inset 0 0 0 calc(var(--sv-p) * 2) var(--sv-frame-lo),
        inset 0 0 0 calc(var(--sv-p) * 3) color-mix(in srgb, var(--sv-scroll), white 55%);
    clip-path: var(--sv-notch);
    font: 24px/1 var(--sv-name-font);
    color: var(--sv-sun-dk);
    text-shadow: 2px 0 0 var(--sv-outline), -2px 0 0 var(--sv-outline), 0 2px 0 var(--sv-outline), 0 -2px 0 var(--sv-outline);
}

#toast-container > .toast-success::before { content: '✓'; color: var(--sv-accent-hi); }
#toast-container > .toast-warning::before { content: '!'; color: var(--sv-frame); }
#toast-container > .toast-error::before { content: '×'; color: var(--sv-mushroom); }

#toast-container > .toast .toast-title {
    font-family: var(--sv-name-font);
    font-weight: 400;
}

#toast-container > .toast .toast-close-button {
    position: absolute;
    right: calc(var(--sv-fw) + 4px);
    top: calc(var(--sv-fw) + 2px);
    color: var(--sv-ink);
    text-shadow: none;
    opacity: 1;
}

/* ===== 快速回复：底部工具栏，一格一个按钮，左上角有编号 ===== */
#send_form > #qr--bar {
    counter-reset: sv-slot;
}

#send_form > #qr--bar .qr--buttons {
    gap: calc(var(--sv-p) * 2);
}

#send_form > #qr--bar .qr--button {
    counter-increment: sv-slot;
    position: relative;
    margin: 0;
    padding: 10px 12px 6px;
    border: var(--sv-p) solid var(--sv-frame-lo);
    border-radius: 0;
    background: color-mix(in srgb, var(--sv-paper), white 25%);
    box-shadow: var(--sv-sunk);
    clip-path: var(--sv-notch);
    color: var(--sv-ink);
    opacity: 1;
}

#send_form > #qr--bar .qr--button::before {
    content: counter(sv-slot);
    position: absolute;
    left: 3px;
    top: 1px;
    font: 12px/1 var(--sv-name-font);
    color: var(--fx-meta);
}

#send_form > #qr--bar .qr--button:hover {
    border-color: var(--sv-select);
    box-shadow: var(--sv-sunk), inset 0 0 0 var(--sv-p) var(--sv-select);
}

/* ===== 输入区：一块对话框纸，细框，四角各缺一格 ===== */
#send_form {
    position: relative;
    isolation: isolate;
    background: none;
    border: none;
    border-radius: 0;
    box-shadow: none;
    padding: calc(var(--sv-tw) + 2px);
    backdrop-filter: none;
    overflow: visible;
}

#send_form::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    background: var(--sv-paper-bands);
    border: var(--sv-p) solid var(--sv-outline);
    box-shadow: var(--sv-ring);
    clip-path: var(--sv-notch);
}

#send_textarea {
    color: var(--sv-ink);
    font-family: var(--sv-font);
}

#send_textarea::placeholder { color: var(--fx-meta); }

#send_form .fa-solid,
#send_form .fa-regular {
    color: var(--sv-ink);
    opacity: 1;
}

/* 装饰：输入框左上角长出一簇叶子 */
#send_form::after {
    content: '';
    position: absolute;
    left: calc(var(--sv-p) * -3);
    top: calc(var(--sv-p) * -8);
    width: 1em;
    height: 1em;
    font-size: var(--sv-p);
    box-shadow: var(--spr-leaves);
    pointer-events: none;
    opacity: var(--sv-deco);
    z-index: 2;
}

/* ===== 世界书 / 预设：开着 = 亮纸格子 + 绿标；关着 = 压暗的格子、虚线框，字照样清楚 ===== */
:root {
    --sv-on-bg: color-mix(in srgb, var(--sv-paper), white 30%);
    --sv-off-bg: color-mix(in srgb, var(--sv-paper), var(--sv-wood-lo) 22%);
}

#world_popup_entries_list .world_entry {
    background: var(--sv-on-bg);
    border: var(--sv-p) solid var(--sv-outline);
    border-left: calc(var(--sv-p) * 3) solid var(--sv-accent);
    border-radius: 0;
    box-shadow: inset var(--sv-p) var(--sv-p) 0 white;
    clip-path: var(--sv-notch);
    margin: 0 0 8px;
}

#world_popup_entries_list .world_entry:not(.disabledWIEntry):has(select[name="entryStateSelector"] option[value="constant"]:checked) {
    border-left-color: var(--SmartThemeQuoteColor);
}

#world_popup_entries_list .world_entry.disabledWIEntry,
#world_popup_entries_list .world_entry.disabledWIEntry:hover {
    opacity: 1;
    filter: none;
    background: var(--sv-off-bg);
    border-style: dashed;
    border-color: var(--sv-wood-lo);
    border-left: calc(var(--sv-p) * 3) dashed var(--sv-wood-lo);
    box-shadow: inset var(--sv-p) var(--sv-p) 0 color-mix(in srgb, var(--sv-off-bg), black 12%);
}

#world_popup_entries_list .world_entry.disabledWIEntry .text_pole,
#world_popup_entries_list .world_entry.disabledWIEntry textarea {
    color: var(--sv-ink);
}

#world_popup_entries_list .killSwitch {
    opacity: 1;
    color: var(--sv-accent);
}

#world_popup_entries_list .disabledWIEntry .killSwitch {
    color: var(--sv-wood-lo);
}

/* 预设顶上「总词符数」：酒馆写死 50% 白 + 黑色模糊投影 */
#completion_prompt_manager .completion_prompt_manager_header {
    color: var(--fx-meta);
}

#completion_prompt_manager .completion_prompt_manager_header_advanced span {
    filter: none;
}

/* 开着的开关：酒馆用引用色（蓝），这里统一成绿 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action {
    color: var(--sv-accent);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    border-radius: 0;
    clip-path: var(--sv-notch);
    margin: 0 0 4px;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) {
    background: var(--sv-on-bg);
    border: var(--sv-p) solid var(--sv-outline);
    border-left: calc(var(--sv-p) * 3) solid var(--sv-accent);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    background: var(--sv-off-bg);
    border: var(--sv-p) dashed var(--sv-wood-lo);
    border-left: calc(var(--sv-p) * 3) dashed var(--sv-wood-lo);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: var(--sv-ink);
    opacity: 1;
}

#completion_prompt_manager #completion_prompt_manager_list .prompt-manager-toggle-action {
    opacity: 1;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .prompt-manager-toggle-action {
    color: var(--sv-wood-lo);
}

/* ===== 日历时钟（装了主题伴侣才有：脚本 themes/farm/farm.js 往 body 里加 #sv_clock；#sheld 横向裁切，挂不进去）
 * 板子、表盘、指针、格子都是脚本画的像素画（.sv-art 里的 SVG，62×38 格），这里只摆字和小图标的位置（单位：格 = --sv-p） ===== */
#sv_clock {
    position: fixed;
    top: calc(var(--topBarBlockSize, 40px) + 10px);
    left: calc((100dvw + var(--sheldWidth)) / 2 + 14px);
    z-index: 30;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    font-family: var(--sv-name-font);
    color: var(--sv-ink);
    filter: drop-shadow(var(--sv-p) var(--sv-p) 0 color-mix(in srgb, var(--sv-outline) 40%, transparent));
}

#sv_clock .sv-pix,
#sv_energy .sv-pix { display: block; }

#sv_clock .sv-face {
    position: relative;
    width: calc(var(--sv-p) * 73);
    height: calc(var(--sv-p) * 40);
}

#sv_clock .sv-art {
    position: absolute;
    left: 0;
    top: 0;
}

/* 第一格星期和日期、第三格时间：米色格子里面 39×8 格 */
#sv_clock .sv-date,
#sv_clock .sv-time {
    position: absolute;
    left: calc(var(--sv-p) * 29);
    width: calc(var(--sv-p) * 39);
    height: calc(var(--sv-p) * 8);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 24px;
    line-height: 1;
    white-space: nowrap;
    text-shadow: 1px 1px 0 var(--sv-scroll-edge);
}

#sv_clock .sv-date { top: calc(var(--sv-p) * 4); }
#sv_clock .sv-time { top: calc(var(--sv-p) * 28); }

/* 中间两个小图标：季节、白天 / 夜里（格子是画好的，这里只放 8×8 的小图，小图都画成正好 8×8、左右对称，才居中） */
#sv_clock .sv-ico {
    position: absolute;
    top: calc(var(--sv-p) * 16);
    width: calc(var(--sv-p) * 8);
    height: calc(var(--sv-p) * 8);
    font-size: var(--sv-p);
}

#sv_clock .sv-season { left: calc(var(--sv-p) * 30); }
#sv_clock .sv-daynight { left: calc(var(--sv-p) * 59); }

#sv_clock .sv-ico::before {
    content: '';
    position: absolute;
    left: -1em;
    top: -1em;
    width: 1em;
    height: 1em;
}

#sv_clock[data-season="spring"] .sv-season::before { box-shadow: var(--spr-spring); }
#sv_clock[data-season="summer"] .sv-season::before { box-shadow: var(--spr-summer); }
#sv_clock[data-season="fall"] .sv-season::before { box-shadow: var(--spr-fall); }
#sv_clock[data-season="winter"] .sv-season::before { box-shadow: var(--spr-winter); }
#sv_clock .sv-daynight::before { box-shadow: var(--spr-sun); }
#sv_clock.sv-night .sv-daynight::before { box-shadow: var(--spr-moon); }

/* 底下吊着的计数牌（40×16 格，上面 3 格是两根小棍）：这个聊天一共几楼 */
#sv_clock .sv-count {
    position: relative;
    width: calc(var(--sv-p) * 40);
    height: calc(var(--sv-p) * 16);
    margin-right: calc(var(--sv-p) * 4);
}

#sv_clock .sv-count b {
    position: absolute;
    left: calc(var(--sv-p) * 2);
    top: calc(var(--sv-p) * 5);
    width: calc(var(--sv-p) * 8);
    height: calc(var(--sv-p) * 8);
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 400;
    font-size: 24px;
    line-height: 1;
    color: var(--sv-outline);
    text-shadow: 1px 1px 0 var(--sv-frame-br);
}

/* 数字：五格，每格 5 格宽（15px），字 12px 宽 + 3px 字距，靠右 */
#sv_clock .sv-num {
    position: absolute;
    left: calc(var(--sv-p) * 12);
    top: calc(var(--sv-p) * 6);
    width: calc(var(--sv-p) * 25);
    height: calc(var(--sv-p) * 7);
    display: flex;
    align-items: center;
    justify-content: flex-end;
    font-size: 24px;
    line-height: 1;
    letter-spacing: 3px;
    color: var(--sv-digit);
    text-shadow: 1px 0 0 currentColor;
}

/* 时钟板上冒出来的叶子 */
#sv_clock .sv-face::after {
    content: '';
    position: absolute;
    right: calc(var(--sv-p) * 3);
    top: calc(var(--sv-p) * -9);
    width: 1em;
    height: 1em;
    font-size: var(--sv-p);
    box-shadow: var(--spr-leaves-flip);
    opacity: var(--sv-deco);
    pointer-events: none;
}

/* 右边面板钉住了就挂到聊天区左边；两边都钉住、或者屏幕太窄，就收起来 */
body:has(#right-nav-panel.pinnedOpen.openDrawer) #sv_clock {
    left: auto;
    right: calc((100dvw + var(--sheldWidth)) / 2 + 14px);
}

body:has(#right-nav-panel.pinnedOpen.openDrawer):has(#left-nav-panel.pinnedOpen.openDrawer) #sv_clock {
    display: none;
}

@media (max-width: 1400px) {
    #sv_clock { display: none; }
}

/* ===== 生成中（装了主题伴侣才有：脚本给 <html> 加 sv-gen）：最后一条角色消息右下角一只一上一下跳的小箭头 ===== */
html.sv-gen #chat .mes.last_mes:not([is_user="true"]) .mes_block::after {
    content: '';
    position: absolute;
    z-index: 4;
    right: calc(var(--sv-col) + var(--sv-fw) + 6px + var(--sv-p) * 12);
    bottom: calc(var(--sv-fw) + 4px + var(--sv-p) * 9);
    width: 1em;
    height: 1em;
    font-size: var(--sv-p);
    box-shadow: var(--spr-down);
    animation: sv-bob 0.8s steps(2, jump-none) infinite alternate;
}

@keyframes sv-bob {
    from { transform: translateY(0); }
    to { transform: translateY(calc(var(--sv-p) * 2)); }
}

body.reduced-motion #chat .mes .mes_block::after { animation: none; }

@media (prefers-reduced-motion: reduce) {
    #chat .mes .mes_block::after,
    #chat .mes[is_user="true"] .mes_block::before { animation: none; }
}

/* 生成中换回复的箭头本来就藏起来；万一没藏，让给小箭头 */
html.sv-gen #chat .mes.last_mes .swipe_left,
html.sv-gen #chat .mes.last_mes .swipeRightBlock { visibility: hidden; }

/* ===== 好感心心（装了主题伴侣才有）：名牌下面一排十颗，点亮的是红的 ===== */
#chat .mes .sv-hearts {
    display: flex;
    gap: var(--sv-heart-px);
    margin: -6px 0 8px;
    font-size: var(--sv-heart-px);
    cursor: pointer;
}

#chat .mes[is_user="true"] .sv-hearts,
#chat .mes[is_system="true"] .sv-hearts { display: none; }

#chat .mes .sv-hearts i {
    --sv-hc: color-mix(in srgb, var(--sv-wood-lo), var(--sv-outline) 45%);
    --sv-hc-hi: var(--sv-hc);
    position: relative;
    width: 7em;
    height: 6em;
    transition: transform 0.1s steps(1);
}

#chat .mes .sv-hearts i::before {
    content: '';
    position: absolute;
    left: -1em;
    top: -1em;
    width: 1em;
    height: 1em;
    box-shadow: var(--spr-heart);
}

#chat .mes .sv-hearts i:hover { transform: translateY(-1em); }

/* ===== 体力条 = 上下文用了多少（装了主题伴侣才有）：电脑竖着挂在聊天区旁边，手机横着贴在输入框上沿
 * 框和顶上的「E」是脚本画的像素画（12 格粗，--sv-elen 格长，帽子 11 格）；装的「体力」是 <i>，按 --sv-e（0~1）涨 ===== */
#sv_energy {
    position: fixed;
    z-index: 30;
    left: calc((100dvw + var(--sheldWidth)) / 2 + 14px);
    bottom: 14px;
    cursor: help;
    filter: drop-shadow(var(--sv-p) var(--sv-p) 0 color-mix(in srgb, var(--sv-outline) 40%, transparent));
}

/* 槽里面 6 格宽，从下往上涨，左边一道亮边、顶上一道亮线；七成黄、九成红 */
#sv_energy i {
    --sv-ec: var(--sv-accent-hi);
    position: absolute;
    left: var(--sv-3);
    bottom: var(--sv-2);
    width: var(--sv-6);
    height: calc(var(--sv-p) * (var(--sv-elen, 70) - 14) * var(--sv-e, 0));
    background: linear-gradient(to right, color-mix(in srgb, var(--sv-ec), white 45%) 0 var(--sv-p), var(--sv-ec) var(--sv-p));
    border-top: var(--sv-p) solid color-mix(in srgb, var(--sv-ec), white 30%);
    box-sizing: border-box;
}

#sv_energy[data-level="none"] i { border-top: none; }
#sv_energy[data-level="mid"] i { --sv-ec: var(--sv-sun); }
#sv_energy[data-level="low"] i { --sv-ec: var(--sv-select); }

/* 横着（手机）：帽子在左，从左往右涨 */
#sv_energy.sv-h i {
    left: calc(var(--sv-p) * 12);
    top: var(--sv-3);
    bottom: auto;
    height: var(--sv-6);
    width: calc(var(--sv-p) * (var(--sv-elen, 60) - 14) * var(--sv-e, 0));
    border-top: none;
    border-right: var(--sv-p) solid color-mix(in srgb, var(--sv-ec), white 30%);
    background: linear-gradient(to bottom, color-mix(in srgb, var(--sv-ec), white 45%) 0 var(--sv-p), var(--sv-ec) var(--sv-p));
}

#sv_energy.sv-h[data-level="none"] i { border-right: none; }

body:has(#right-nav-panel.pinnedOpen.openDrawer) #sv_energy {
    left: auto;
    right: calc((100dvw + var(--sheldWidth)) / 2 + 14px);
}

body:has(#right-nav-panel.pinnedOpen.openDrawer):has(#left-nav-panel.pinnedOpen.openDrawer) #sv_energy {
    display: none;
}

@media (min-width: 1001px) and (max-width: 1400px) {
    #sv_energy { display: none; }
}

/* ===== 提示词词符明细（消息上的「提示词」按钮）：结算单 —— 卷轴标题、一项一行带虚线引线，数字放进计数框 ===== */
.popup:has(.tokenGraph) {
    padding: calc(var(--sv-fw) + 6px) calc(var(--sv-fw) + 12px);
    width: min(760px, 96vw);
    max-width: 96vw;
    font-family: var(--sv-font);
}

.popup:has(.tokenGraph) .popup-content > h3:first-child {
    margin: 0 0 12px;
    padding: 4px 12px;
    font-size: 24px;
    line-height: 1.5;
    background: linear-gradient(to bottom,
        color-mix(in srgb, var(--sv-scroll), white 40%) 0 20%,
        var(--sv-scroll) 20% 72%,
        var(--sv-scroll-edge) 72%);
    border: var(--sv-p) solid var(--sv-outline);
    border-inline-width: calc(var(--sv-p) * 3);
    text-shadow: 1px 1px 0 var(--sv-scroll-edge);
}

.popup:has(.tokenGraph) .popup-content > h3:first-child .menu_button { font-size: 16px; }

.popup:has(.tokenGraph) hr {
    height: var(--sv-p);
    margin: 12px 0;
    border: none;
    background: repeating-linear-gradient(to right, var(--sv-frame-lo) 0 calc(var(--sv-p) * 2), transparent calc(var(--sv-p) * 2) calc(var(--sv-p) * 4));
    opacity: 1;
}

/* 左边那根柱：一格一种东西，像装箱的货 */
.popup .tokenGraph {
    flex: 0 0 auto;
    width: 25%;
    min-height: 280px;
    border: var(--sv-p) solid var(--sv-outline);
    border-radius: 0;
    background: var(--sv-slot);
    box-shadow: var(--sv-sunk);
}

.popup .tokenGraph > div { box-shadow: inset 0 -1px 0 color-mix(in srgb, var(--sv-outline) 45%, transparent); }
.popup .tokenGraph > div:nth-child(1) { background-color: var(--sv-wood-lo) !important; }
.popup .tokenGraph > div:nth-child(2) { background-color: var(--sv-petal) !important; }
.popup .tokenGraph > div:nth-child(3) { background-color: var(--sv-mushroom) !important; }
.popup .tokenGraph > div:nth-child(4) { background-color: var(--sv-sun) !important; }
.popup .tokenGraph > div:nth-child(5) { background-color: var(--sv-leaf) !important; }
.popup .tokenGraph > div:nth-child(6) { background-color: var(--sv-sky) !important; }
.popup .tokenGraph > div:nth-child(7) { background-color: var(--sv-petal-dk) !important; }

/* 大项：一行字 + 虚线引线 + 计数框；前面一个小色块，和柱子对上（酒馆原来是给字上色，在纸上看不清） */
.popup:has(.tokenGraph) .flex-container > .flex1[style*="color"] {
    color: var(--sv-ink) !important;
    display: flex;
    align-items: center;
    gap: 8px;
}

.popup:has(.tokenGraph) .flex-container > .flex1[style*="color"]::before {
    content: '';
    flex: none;
    width: calc(var(--sv-p) * 4);
    height: calc(var(--sv-p) * 4);
    border: var(--sv-p) solid var(--sv-outline);
    background: var(--sv-sw, var(--sv-slot));
}

.popup:has(.tokenGraph) .flex1[style*="grey"] { --sv-sw: var(--sv-wood-lo); }
.popup:has(.tokenGraph) .flex1[style*="indianred"] { --sv-sw: var(--sv-mushroom); }
.popup:has(.tokenGraph) .flex1[style*="gold"] { --sv-sw: var(--sv-sun); }
.popup:has(.tokenGraph) .flex1[style*="palegreen"] { --sv-sw: var(--sv-leaf); }
.popup:has(.tokenGraph) .flex1[style*="cornflowerblue"] { --sv-sw: var(--sv-sky); }
.popup:has(.tokenGraph) .flex1[style*="mediumpurple"] { --sv-sw: var(--sv-petal-dk); }

.popup:has(.tokenGraph) .flex-container > .flex1 + div {
    min-width: 76px;
    padding: 0 6px;
    text-align: right;
    font-family: var(--sv-name-font);
}

.popup:has(.tokenGraph) .flex-container:has(> .flex1[style*="color"]),
.popup:has(.tokenGraph) .justifyLeft > .flexFlowColumns > .flex-container {
    align-items: center;
    margin-top: 6px;
    padding-bottom: 2px;
    background: repeating-linear-gradient(to right, var(--fx-hairline) 0 var(--sv-p), transparent var(--sv-p) calc(var(--sv-p) * 3)) left bottom / 100% 1px no-repeat;
}

.popup:has(.tokenGraph) .flex-container:has(> .flex1[style*="color"]) > .flex1 + div,
.popup:has(.tokenGraph) .justifyLeft > .flexFlowColumns > .flex-container > .flex1 + div {
    height: 28px;
    line-height: 22px;
    font-size: 24px;
    color: var(--sv-digit);
    border: var(--sv-p) solid var(--sv-frame-lo);
    background: color-mix(in srgb, var(--sv-scroll), var(--sv-scroll-edge) 25%);
    box-shadow: var(--sv-sunk);
    box-sizing: border-box;
}

/* 小项：12px 像素字，次要色 */
.popup:has(.tokenGraph) .tokenItemizingSubclass {
    font-family: var(--sv-name-font);
    font-size: 12px;
    line-height: 20px;
    color: var(--fx-meta);
}

.popup:has(.tokenGraph) .justifyLeft,
.popup:has(.tokenGraph) .flex-container > .flex1 { text-align: left; }

.popup:has(.tokenGraph) .flex-container > .flex1.tokenItemizingSubclass { padding-left: 14px; }

/* 右边那列明细占满剩下的宽度 */
.popup:has(.tokenGraph) .tokenGraph + .wide50p { flex: 1; width: auto; }

/* 底下的合计：嵌在橙色木条里的一块，和计数牌一样 */
.popup:has(.tokenGraph) .justifyLeft > .flexFlowColumns {
    padding: calc(var(--sv-p) * 2 + 4px) calc(var(--sv-p) * 2 + 10px);
    border: 1px solid var(--sv-outline);
    background: var(--sv-scroll);
    box-shadow: inset 0 0 0 var(--sv-p) var(--sv-frame), inset 0 0 0 calc(var(--sv-p) * 2) var(--sv-frame-lo);
}

.popup:has(.tokenGraph) #rawPromptWrapper {
    padding: 8px 10px;
    background: var(--sv-slot);
    border: var(--sv-p) solid var(--sv-outline);
    box-shadow: var(--sv-sunk);
}

/* ===== 手机：木板变成顶上一条，头像在左、名牌在右 ===== */
@media (max-width: 1000px) {
    #chat .mes:not([is_user="true"]) {
        grid-template-columns: minmax(0, 1fr);
        min-height: 0;
    }

    #chat .mes:not([is_user="true"]) .mesAvatarWrapper {
        grid-column: 1;
        grid-row: 1;
        margin: calc(var(--sv-fw) * -1) calc(var(--sv-fw) * -1) 0;
        padding: calc(var(--sv-fw) + 12px) calc(var(--sv-fw) + 10px) calc(var(--sv-6) + 12px);
        flex-direction: row;
        align-items: flex-end;
        flex-wrap: wrap;
        gap: 2px 8px;
        /* 底边一根横木，下面压一道纸的阴影；上沿一道暗影 */
        background: var(--sv-hlog) left bottom / 100% var(--sv-6) no-repeat, var(--sv-wood);
        box-shadow:
            0 var(--sv-p) 0 0 var(--sv-paper-sh),
            inset 0 calc(var(--sv-fw) + var(--sv-p)) 0 0 var(--sv-wood-lo);
    }

    #chat .mes:not([is_user="true"]) .mesAvatarWrapper::before,
    #chat .mes:not([is_user="true"]) .mesAvatarWrapper::after {
        inset: 0 0 var(--sv-6) 0;
    }

    #chat .mes:not([is_user="true"]) .mes_block { grid-row: 2; }

    #chat .mes .mesAvatarWrapper .avatar,
    body.big-avatars #chat .mes .mesAvatarWrapper .avatar,
    body.square-avatars #chat .mes .mesAvatarWrapper .avatar,
    body.rounded-avatars #chat .mes .mesAvatarWrapper .avatar {
        margin: calc(var(--sv-p) * 4) calc(var(--sv-p) * 6) calc(var(--sv-p) * 4) calc(var(--sv-p) * 4);
    }

    #chat .mes:not([is_user="true"]) .name_text {
        top: calc(var(--sv-fw) + 12px + var(--sv-p) * 4 + (var(--sv-abox) - var(--sv-sh)) / 2);
        left: calc(var(--sv-fw) + 10px + var(--sv-abox) + var(--sv-p) * 14);
        right: calc(var(--sv-fw) + 10px);
        width: auto;
    }

    #chat .mes:not([is_user="true"]) .swipeRightBlock { right: calc(var(--sv-fw) + 6px); }
    #chat .mes:not([is_user="true"]) .swipe_left { right: calc(var(--sv-fw) + 6px + var(--sv-p) * 14 + 34px); }

    #chat .mes[is_user="true"] .mes_block::before { top: calc(var(--sv-fw) + 40px); }

    #top-settings-holder > .drawer > .drawer-toggle,
    #top-settings-holder > .drawer > .drawer-icon {
        margin: 2px 1px calc(var(--sv-p) + 2px) 0;
        padding: var(--sv-p);
    }

    html.sv-gen #chat .mes.last_mes:not([is_user="true"]) .mes_block::after {
        right: calc(var(--sv-fw) + 6px + var(--sv-p) * 12);
    }

    /* 心心：手机上在名牌下面 */
    #chat .mes .sv-hearts {
        position: absolute;
        z-index: 2;
        top: calc(var(--sv-fw) + 12px + var(--sv-p) * 4 + (var(--sv-abox) + var(--sv-sh)) / 2 + 8px);
        left: calc(var(--sv-fw) + 10px + var(--sv-abox) + var(--sv-p) * 14);
        margin: 0;
    }

    /* 体力条：横着贴在输入框右上角 */
    #form_sheld { position: relative; }

    #sv_energy {
        position: absolute;
        left: auto;
        right: 12px;
        bottom: calc(100% - var(--sv-p));
    }
}
